DROP TABLE IF EXISTS `appointment_histories`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `appointment_histories` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `action` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `changed_at` datetime(6) NOT NULL,
  `changed_by_role` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `changed_by_user_id` bigint DEFAULT NULL,
  `new_date` date DEFAULT NULL,
  `new_end_time` time(6) DEFAULT NULL,
  `new_start_time` time(6) DEFAULT NULL,
  `new_status` enum('CANCELLED','CHECKED_IN','COMPLETED','CONFIRMED','IN_PROGRESS','NO_SHOW','PENDING','RESCHEDULED') COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `old_date` date DEFAULT NULL,
  `old_end_time` time(6) DEFAULT NULL,
  `old_start_time` time(6) DEFAULT NULL,
  `old_status` enum('CANCELLED','CHECKED_IN','COMPLETED','CONFIRMED','IN_PROGRESS','NO_SHOW','PENDING','RESCHEDULED') COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `reason` text COLLATE utf8mb4_unicode_ci,
  `appointment_id` bigint NOT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_history_appointment` (`appointment_id`),
  KEY `idx_history_changed_at` (`changed_at`),
  CONSTRAINT `FK2f1si2ufo0w8pmhqwts1kpc1v` FOREIGN KEY (`appointment_id`) REFERENCES `appointments` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=62 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
