INSERT INTO `medical_records` VALUES (1,'2026-02-19 18:36:32.000000','2026-02-19 18:36:32.000000',NULL,'Đau đầu, chóng mặt, huyết áp cao','Tăng huyết áp độ 2','I10','2026-03-05','Tái khám sau 2 tuần, mang theo sổ theo dõi huyết áp',_binary '\0',NULL,'Tim đều, phổi trong, bụng mềm. Không phù chi.','Amlodipine 5mg x 1 viên/ngày\nLosartan 50mg x 1 viên/ngày','Bệnh nhân nam 43 tuổi, tiền sử tăng huyết áp 5 năm. Đau đầu tăng 1 tuần nay.','MR-20260219-001','Điều chỉnh thuốc hạ áp. Theo dõi huyết áp tại nhà.','2026-02-19','{\"height_cm\": 170, \"weight_kg\": 75, \"heart_rate\": 82, \"temperature\": 36.5, \"blood_pressure\": \"150/95\"}',1001,10,1);
